function longestSubarray(nums) {
  // Try deleting each position, then measure the longest run of 1s that is left.
  let result = 0;
  for (let skip = 0; skip < nums.length; skip++) {
    const rest = nums.filter((_, i) => i !== skip);
    let run = 0;
    for (const v of rest) {
      run = v === 1 ? run + 1 : 0;
      result = Math.max(result, run);
    }
  }
  return result;
}

