function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  // Vary how often zeros appear, from none at all to about half of the values.
  const zeroChance = rand() < 0.15 ? 0 : rand() < 0.5 ? rand() * 0.1 : rand() * 0.5;
  return [Array.from({ length: n }, () => rand() < zeroChance ? 0 : 1)];
}
